const input = $json.body || $json.query || $json || {};
const headers = $json.headers || {};
const payload = { ...input };
payload.webhook_received_at = new Date().toISOString();
payload.webhook_source = 'Normalize Webhook Payload';
payload.request_header_secret_present = Boolean(headers['x-cqr-admin-secret'] || headers['X-CQR-Admin-Secret']);
return [{ json: payload }];

const config = $('Set Runtime Config').first().json;
const targetMonth = config.target_month;
const targetGamesCsv = config.target_games_csv || 'ALL';
const targetGames = targetGamesCsv === 'ALL' ? null : targetGamesCsv.split(',').map(v => v.trim()).filter(Boolean);
const batchId = config.batch_id || 'BATCH-' + new Date().toISOString().replace(/[-:.]/g, '').slice(0, 15) + 'Z';
const requireRawCheck = String(config.require_raw_check || 'true').toLowerCase() !== 'false';

const masterFileByGame = {
  CBM_TH: '1ofe69uOTknTY2RcoLjAkPXUQ0sUQjZPgJ-oIRCD5hKM',
  CBM_SEA: '1B_eXcoxJyKnV_wH4zyPHqDg2lmS_gfGJ-9cxaF5h5bY',
  CBPC_TH: '18uiKPUsWeByiT2jOv_aaCdq_xlpcMkw1B6glN8NRyF4',
  CBPC_SEA: '1p5qN81Vg5rN08XldlQDV_fQTuqRaS1xpBk-aWuQb-9I'
};

const requiredTabs = [
  { sheet_type: 'registered', tab_name: `Registered_${targetMonth}` },
  { sheet_type: 'dau', tab_name: `DAU_${targetMonth}` },
  { sheet_type: 'returners', tab_name: `Returners_${targetMonth}` },
  { sheet_type: 'late_starters', tab_name: `Late_Starters_${targetMonth}` },
  { sheet_type: 'login', tab_name: `Login_${targetMonth}` }
];

function rowsFrom(nodeName) {
  try { return $(nodeName).all().map(item => item.json).filter(row => !row.error); }
  catch (error) { return []; }
}
function latestBy(rows, field) {
  return [...rows].sort((a, b) => String(b[field] || b.checked_at || b.run_finished_at || '').localeCompare(String(a[field] || a.checked_at || a.run_finished_at || '')))[0] || null;
}
function period(row) { return String(row.period_key || row.month || row.target_month || '').trim(); }

const sourceRows = rowsFrom('Read Central DB - SourceFiles');
const dataIndexRows = rowsFrom('Read Central DB - DataIndex');
const rawCheckRows = rowsFrom('Read Central DB - RawIngestionLogs');
const activeRows = sourceRows.filter(row => String(row.status || '').toLowerCase() === 'active');
const filteredRows = targetGames ? activeRows.filter(row => targetGames.includes(row.game_code)) : activeRows;

function latestHashFor(gameCode) {
  const rows = dataIndexRows.filter(row =>
    row.game_code === gameCode &&
    period(row) === targetMonth &&
    String(row.data_hash || '').trim()
  );
  rows.sort((a, b) => String(b.last_updated_at || b.updated_at || '').localeCompare(String(a.last_updated_at || a.updated_at || '')));
  return rows[0]?.data_hash || '';
}
function latestRawCheckFor(gameCode) {
  return latestBy(rawCheckRows.filter(row => row.game_code === gameCode && period(row) === targetMonth), 'checked_at');
}

const units = [];
for (const row of filteredRows) {
  const rawCheck = latestRawCheckFor(row.game_code);
  const rawStatus = String(rawCheck?.status || '').toLowerCase();
  if (requireRawCheck && rawStatus !== 'raw_ready') {
    units.push({ json: {
      run_id: 'RUN-' + row.game_code + '-' + targetMonth + '-' + new Date().toISOString().replace(/[-:.]/g, '').slice(0, 15) + 'Z',
      batch_id: batchId,
      run_mode: config.run_mode,
      target_month: targetMonth,
      game_code: row.game_code,
      source_file_id: row.source_file_id,
      source_file_name: row.source_file_name,
      source_folder_id: row.source_folder_id,
      master_file_id: masterFileByGame[row.game_code] || row.master_file_id || '',
      schema_version: row.schema_version,
      last_modified_at: row.last_modified_at,
      last_data_hash: latestHashFor(row.game_code),
      raw_check_id: rawCheck?.raw_check_id || '',
      raw_check_status: rawCheck?.status || 'missing_raw_check',
      raw_data_hash: rawCheck?.raw_data_hash || '',
      raw_check_blocked: true,
      raw_check_message: rawCheck?.message || 'Raw check is required before build.',
      dedupe_source: 'Central DB DataIndex + RawIngestionLogs',
      required_tabs: requiredTabs,
      missing_tab_policy: config.missing_tab_policy,
      prompt_version: config.prompt_version,
      central_db_id: config.central_db_id
    }});
    continue;
  }
  units.push({ json: {
    run_id: 'RUN-' + row.game_code + '-' + targetMonth + '-' + new Date().toISOString().replace(/[-:.]/g, '').slice(0, 15) + 'Z',
    batch_id: batchId,
    run_mode: config.run_mode,
    target_month: targetMonth,
    game_code: row.game_code,
    source_file_id: row.source_file_id,
    source_file_name: row.source_file_name,
    source_folder_id: row.source_folder_id,
    master_file_id: masterFileByGame[row.game_code] || row.master_file_id || '',
    schema_version: row.schema_version,
    last_modified_at: row.last_modified_at,
    last_data_hash: latestHashFor(row.game_code),
    raw_check_id: rawCheck?.raw_check_id || '',
    raw_check_status: rawCheck?.status || 'not_checked',
    raw_data_hash: rawCheck?.raw_data_hash || '',
    raw_check_blocked: false,
    raw_check_message: rawCheck?.message || '',
    dedupe_source: 'Central DB DataIndex + RawIngestionLogs',
    required_tabs: requiredTabs,
    missing_tab_policy: config.missing_tab_policy,
    prompt_version: config.prompt_version,
    central_db_id: config.central_db_id
  }});
}
return units;

const unit = $json;
const tabPlan = unit.required_tabs.map(tab => ({
  ...tab,
  tab_key: `${unit.game_code}|${unit.target_month}|${tab.tab_name}`,
  source_file_id: unit.source_file_id,
  game_code: unit.game_code,
  period_key: unit.target_month,
  status: 'planned'
}));

return [{
  json: {
    ...unit,
    tab_plan: tabPlan,
    quality_signals: [],
    pipeline_status: 'planned'
  }
}];

const unit = $('Prepare Tab Plan').first().json;
const now = new Date().toISOString();
const runId = unit.run_id || 'RUN-' + unit.game_code + '-' + unit.target_month + '-' + now.replace(/[-:.]/g, '').slice(0, 15) + 'Z';
const batchId = unit.batch_id || 'BATCH-' + now.replace(/[-:.]/g, '').slice(0, 15) + 'Z';
const rawCheckId = unit.raw_check_id || '';
const rawCheckStatus = unit.raw_check_status || 'not_checked';
const month = unit.target_month;
const gameCode = unit.game_code;
const masterFileId = unit.master_file_id || '';
const centralDbId = unit.central_db_id || $('Set Runtime Config').first().json.central_db_id;

function rowsFrom(name) {
  try {
    return $(name).all().map(item => item.json).filter(row => !row.error);
  } catch (error) {
    return [];
  }
}
function errorsFrom(name) {
  try {
    return $(name).all().map(item => item.json).filter(row => row.error).map(row => row.error);
  } catch (error) {
    return [error.message];
  }
}
function parseDate(value) {
  if (!value) return null;
  if (value instanceof Date) return value;
  const s = String(value).trim();
  if (!s) return null;
  let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return new Date(Date.UTC(Number(m[3]), Number(m[2]) - 1, Number(m[1])));
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? null : d;
}
function dateKey(value) {
  const d = parseDate(value);
  return d ? d.toISOString().slice(0, 10) : '';
}
function weekStart(value) {
  const d = parseDate(value);
  if (!d) return '';
  const day = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() - day + 1);
  return d.toISOString().slice(0, 10);
}
function weekEnd(start) {
  if (!start) return '';
  const d = new Date(start + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + 6);
  return d.toISOString().slice(0, 10);
}
function channelOf(row) {
  const raw = String(row.ads_ref || row.channel || '').trim();
  if (!raw) return 'Organic / Unknown';
  const low = raw.toLowerCase();
  if (low.includes('facebook') || low.includes('fb')) return 'Facebook Ads';
  if (low.includes('google')) return 'Google Ads';
  if (low.includes('inapp') || low.includes('in_app')) return 'In-App Register';
  if (low.includes('organic')) return 'Organic / Unknown';
  return raw;
}
function numberValue(value) {
  const n = Number(String(value ?? '').replace(/,/g, ''));
  return Number.isFinite(n) ? n : 0;
}
function boolFlag(value) {
  const text = String(value ?? '').trim().toLowerCase();
  if (['1', 'true', 'yes', 'y'].includes(text)) return 1;
  if (['0', 'false', 'no', 'n', ''].includes(text)) return 0;
  return Number(value) ? 1 : 0;
}
function rate(num, den) {
  return den > 0 ? +(num / den).toFixed(6) : '';
}
function simpleHash(value) {
  const text = JSON.stringify(value);
  let hash = 0;
  for (let i = 0; i < text.length; i++) hash = ((hash << 5) - hash + text.charCodeAt(i)) | 0;
  return Math.abs(hash).toString(36);
}
function summarizeTab(nodeName, sheetType, tabName) {
  const rows = rowsFrom(nodeName);
  const errors = errorsFrom(nodeName);
  const status = errors.length ? 'partial' : (rows.length ? 'ready' : 'no_data');
  return { rows, errors, status, sheetType, tabName };
}
function hasAnyHeader(rows, headers) {
  if (!rows.length) return false;
  return headers.some(header => Object.prototype.hasOwnProperty.call(rows[0], header));
}
function missingHeaders(rows, required) {
  if (!rows.length) return required;
  return required.filter(header => !Object.prototype.hasOwnProperty.call(rows[0], header));
}
function getRegisterDate(row) {
  return row.register_date || row.register_at || '';
}
function getLoginDate(row) {
  return row.login_date || row.login_day || '';
}
function getLoginDays(row) {
  return numberValue(row.login_days_in_month ?? row.distinct_login_days);
}
function usernameKey(row) {
  return String(row.username || '').trim().toLowerCase();
}

const tabs = {
  registered: summarizeTab('Read Raw - Registered', 'registered', 'Registered_' + month),
  dau: summarizeTab('Read Raw - DAU', 'dau', 'DAU_' + month),
  returners: summarizeTab('Read Raw - Returners', 'returners', 'Returners_' + month),
  late_starters: summarizeTab('Read Raw - Late Starters', 'late_starters', 'Late_Starters_' + month),
  login: summarizeTab('Read Raw - Login', 'login', 'Login_' + month)
};

const schemaIssues = [];
const registeredMissing = missingHeaders(tabs.registered.rows, ['username', 'ads_ref', 'first_login_date']);
if (tabs.registered.rows.length && !hasAnyHeader(tabs.registered.rows, ['register_date', 'register_at'])) registeredMissing.push('register_date/register_at');
const dauMissing = missingHeaders(tabs.dau.rows, ['login_date', 'dau']);
const loginMissing = missingHeaders(tabs.login.rows, ['username', 'login_d1', 'login_d3', 'login_d7', 'login_d14', 'player_type']);
if (tabs.registered.rows.length && registeredMissing.length) schemaIssues.push({ sheetType: 'registered', severity: 'error', message: 'Registered schema missing: ' + registeredMissing.join(', ') });
if (tabs.dau.rows.length && dauMissing.length && !hasAnyHeader(tabs.dau.rows, ['login_day'])) schemaIssues.push({ sheetType: 'dau', severity: 'error', message: 'DAU schema missing: ' + dauMissing.join(', ') });
if (tabs.login.rows.length && loginMissing.length) schemaIssues.push({ sheetType: 'login', severity: 'error', message: 'Login schema missing: ' + loginMissing.join(', ') });
if (!tabs.registered.rows.length) schemaIssues.push({ sheetType: 'registered', severity: 'error', message: 'Registered tab has no rows.' });
if (!tabs.login.rows.length) schemaIssues.push({ sheetType: 'login', severity: 'warning', message: 'Login tab has no rows; retention and player_type will default to blank/0.' });

const loginByUsername = new Map();
for (const row of tabs.login.rows) {
  const key = usernameKey(row);
  if (key && !loginByUsername.has(key)) loginByUsername.set(key, row);
}

const joinedCohortRows = tabs.registered.rows.map((registeredRow, index) => {
  const loginRow = loginByUsername.get(usernameKey(registeredRow)) || {};
  return { registeredRow, loginRow, rowIndex: index + 1, hasLogin: Object.keys(loginRow).length > 0 };
});
const missingLoginCount = joinedCohortRows.filter(row => !row.hasLogin).length;
if (missingLoginCount) schemaIssues.push({ sheetType: 'login_join', severity: 'warning', message: missingLoginCount + ' registered users do not have matching Login rows; retention defaults to 0.' });

const dataHash = simpleHash({
  gameCode,
  month,
  schema: 'production_registered_login_join_v1',
  counts: Object.fromEntries(Object.entries(tabs).map(([k, v]) => [k, v.rows.length])),
  registeredSample: tabs.registered.rows.slice(0, 5),
  loginSample: tabs.login.rows.slice(0, 5),
  joinedSample: joinedCohortRows.slice(0, 5).map(item => ({ username: item.registeredRow.username, hasLogin: item.hasLogin, player_type: item.loginRow.player_type || '' }))
});
const dedupeKey = gameCode + '|' + month;
const previousDataHash = unit.last_data_hash || '';
const sameHash = previousDataHash && previousDataHash === dataHash;
const differentHashSamePeriod = previousDataHash && previousDataHash !== dataHash && unit.run_mode !== 'force';
const shouldSkipWrite = unit.run_mode !== 'force' && sameHash;
const rawCheckBlocked = Boolean(unit.raw_check_blocked);
const needsReview = Boolean(differentHashSamePeriod || rawCheckBlocked);
const importId = 'IMP-' + gameCode + '-' + month + '-' + dataHash;

const rawImportRows = Object.values(tabs).map(tab => ({
  import_id: importId + '-' + tab.sheetType,
  run_id: runId,
  source_file_id: unit.source_file_id,
  source_file_name: unit.source_file_name,
  source_tab_name: tab.tabName,
  game_code: gameCode,
  period_key: month,
  month,
  sheet_type: tab.sheetType,
  imported_at: now,
  import_status: tab.status,
  row_count: tab.rows.length,
  data_hash: dataHash,
  notes: tab.errors.join(' | ')
}));

const userCohortRows = joinedCohortRows.map(item => {
  const r = item.registeredRow;
  const l = item.loginRow;
  const registerAt = getRegisterDate(r);
  return {
    cohort_id: 'UC-' + gameCode + '-' + month + '-' + (r.username || item.rowIndex),
    run_id: runId,
    game_code: gameCode,
    period_key: month,
    month,
    username: r.username || '',
    country_code: r.country_code || l.country_code || '',
    ads_ref: r.ads_ref || l.ads_ref || '',
    channel: channelOf(r.ads_ref ? r : l),
    register_at: registerAt,
    register_date: dateKey(registerAt),
    first_login_date: r.first_login_date || l.first_login_date || '',
    last_login_date: r.last_login_date || l.last_login_date || '',
    distinct_login_days: getLoginDays(l) || getLoginDays(r),
    retained_d1: boolFlag(l.login_d1 ?? r.retained_d1),
    retained_d3: boolFlag(l.login_d3 ?? r.retained_d3),
    retained_d7: boolFlag(l.login_d7 ?? r.retained_d7),
    retained_d14: boolFlag(l.login_d14 ?? r.retained_d14),
    retained_d30: boolFlag(l.login_d30 ?? r.retained_d30),
    eligible_d1: item.hasLogin ? 1 : 0,
    eligible_d3: item.hasLogin ? 1 : 0,
    eligible_d7: item.hasLogin ? 1 : 0,
    eligible_d14: item.hasLogin ? 1 : 0,
    eligible_d30: l.login_d30 !== undefined || r.retained_d30 !== undefined ? (item.hasLogin ? 1 : 0) : 0,
    player_type: l.player_type || r.player_type || '',
    source_file_id: unit.source_file_id,
    source_tab_name: tabs.registered.tabName,
    imported_at: now,
    data_hash: dataHash
  };
});

const dauDailyRows = tabs.dau.rows.map(row => {
  const d = dateKey(getLoginDate(row));
  return {
    dau_id: 'DAU-' + gameCode + '-' + d,
    run_id: runId,
    game_code: gameCode,
    period_key: month,
    month,
    login_day: getLoginDate(row),
    login_date: d,
    date: d,
    dau: numberValue(row.dau),
    source_file_id: unit.source_file_id,
    source_tab_name: tabs.dau.tabName,
    imported_at: now,
    updated_at: now,
    data_hash: dataHash
  };
});

const returnerRows = tabs.returners.rows.map(row => {
  const registerAt = getRegisterDate(row);
  return {
    returner_id: 'RET-' + gameCode + '-' + month + '-' + (row.username || row.row_number),
    run_id: runId,
    game_code: gameCode,
    period_key: month,
    month,
    username: row.username || '',
    country_code: row.country_code || '',
    ads_ref: row.ads_ref || '',
    channel: channelOf(row),
    register_at: registerAt,
    register_date: dateKey(registerAt),
    first_login_date: row.first_login_date || '',
    last_login_date: row.last_login_date || '',
    login_days_in_month: getLoginDays(row),
    source_file_id: unit.source_file_id,
    source_tab_name: tabs.returners.tabName,
    imported_at: now,
    data_hash: dataHash
  };
});

const lateFirstLoginRows = tabs.late_starters.rows.map(row => {
  const registerAt = getRegisterDate(row);
  return {
    late_id: 'LATE-' + gameCode + '-' + month + '-' + (row.username || row.row_number),
    run_id: runId,
    game_code: gameCode,
    period_key: month,
    month,
    username: row.username || '',
    country_code: row.country_code || '',
    ads_ref: row.ads_ref || '',
    channel: channelOf(row),
    register_at: registerAt,
    register_date: dateKey(registerAt),
    first_login_date: row.first_login_date || '',
    days_to_first_login: row.days_to_first_login ?? '',
    login_days_in_month: getLoginDays(row),
    source_file_id: unit.source_file_id,
    source_tab_name: tabs.late_starters.tabName,
    imported_at: now,
    data_hash: dataHash
  };
});

function aggregateCohort(rows, keyFn) {
  const buckets = new Map();
  for (const row of rows) {
    const keyData = keyFn(row);
    if (!keyData.key) continue;
    if (!buckets.has(keyData.key)) buckets.set(keyData.key, {
      ...keyData,
      reg: 0,
      retained_d1: 0,
      retained_d3: 0,
      retained_d7: 0,
      retained_d14: 0,
      retained_d30: 0,
      eligible_d1: 0,
      eligible_d3: 0,
      eligible_d7: 0,
      eligible_d14: 0,
      eligible_d30: 0
    });
    const b = buckets.get(keyData.key);
    b.reg += 1;
    b.retained_d1 += numberValue(row.retained_d1);
    b.retained_d3 += numberValue(row.retained_d3);
    b.retained_d7 += numberValue(row.retained_d7);
    b.retained_d14 += numberValue(row.retained_d14);
    b.retained_d30 += numberValue(row.retained_d30);
    b.eligible_d1 += numberValue(row.eligible_d1);
    b.eligible_d3 += numberValue(row.eligible_d3);
    b.eligible_d7 += numberValue(row.eligible_d7);
    b.eligible_d14 += numberValue(row.eligible_d14);
    b.eligible_d30 += numberValue(row.eligible_d30);
  }
  return [...buckets.values()].map(b => ({
    run_id: runId,
    game_code: gameCode,
    period_key: month,
    month,
    channel: b.channel,
    reg: b.reg,
    retained_d1: b.retained_d1,
    retained_d3: b.retained_d3,
    retained_d7: b.retained_d7,
    retained_d14: b.retained_d14,
    retained_d30: b.retained_d30,
    eligible_d1: b.eligible_d1,
    eligible_d3: b.eligible_d3,
    eligible_d7: b.eligible_d7,
    eligible_d14: b.eligible_d14,
    eligible_d30: b.eligible_d30,
    d1_rate: rate(b.retained_d1, b.eligible_d1),
    d3_rate: rate(b.retained_d3, b.eligible_d3),
    d7_rate: rate(b.retained_d7, b.eligible_d7),
    d14_rate: rate(b.retained_d14, b.eligible_d14),
    d30_rate: rate(b.retained_d30, b.eligible_d30),
    imported_at: now,
    data_hash: dataHash,
    ...b.extra
  }));
}
const channelMonthlyRows = aggregateCohort(userCohortRows, row => ({ key: channelOf(row), channel: channelOf(row), extra: { monthly_id: 'CM-' + gameCode + '-' + month + '-' + channelOf(row) } }));
const channelDailyRows = aggregateCohort(userCohortRows, row => {
  const d = dateKey(row.register_date || row.register_at);
  const ch = channelOf(row);
  return { key: d + '|' + ch, channel: ch, extra: { daily_id: 'CD-' + gameCode + '-' + d + '-' + ch, register_date: d, date: d } };
});
const channelWeeklyRows = aggregateCohort(userCohortRows, row => {
  const ws = weekStart(row.register_date || row.register_at);
  const ch = channelOf(row);
  return { key: ws + '|' + ch, channel: ch, extra: { weekly_id: 'CW-' + gameCode + '-' + ws + '-' + ch, week_start_date: ws, week_end_date: weekEnd(ws) } };
});

const qualitySignalRows = [];
for (const tab of Object.values(tabs)) {
  if (tab.status !== 'ready') qualitySignalRows.push({
    signal_id: 'QS-' + gameCode + '-' + month + '-' + tab.sheetType + '-' + Date.now(),
    run_id: runId,
    game_code: gameCode,
    period_key: month,
    signal_type: 'raw_tab_status',
    severity: tab.status === 'partial' ? 'warning' : 'info',
    message: tab.tabName + ' status=' + tab.status + ', rows=' + tab.rows.length + (tab.errors.length ? ', errors=' + tab.errors.join(' | ') : ''),
    detected_at: now,
    status: 'open',
    data_hash: dataHash
  });
}
for (const issue of schemaIssues) {
  qualitySignalRows.push({
    signal_id: 'QS-' + gameCode + '-' + month + '-' + issue.sheetType + '-' + Date.now(),
    run_id: runId,
    game_code: gameCode,
    period_key: month,
    signal_type: 'schema_validation',
    severity: issue.severity,
    message: issue.message,
    detected_at: now,
    status: 'open',
    data_hash: dataHash
  });
}
if (!masterFileId) qualitySignalRows.push({ signal_id: 'QS-' + gameCode + '-' + month + '-missing-master', run_id: runId, game_code: gameCode, period_key: month, signal_type: 'config', severity: 'error', message: 'Master file id is missing for this game_code.', detected_at: now, status: 'open', data_hash: dataHash });
if (needsReview) qualitySignalRows.push({ signal_id: 'QS-' + gameCode + '-' + month + '-hash-needs-review-' + Date.now(), run_id: runId, game_code: gameCode, period_key: month, signal_type: 'dedupe_hash_guard', severity: 'warning', message: 'Same game/month has different data_hash. previous=' + previousDataHash + ', current=' + dataHash + '. Stop write until cleanup/force run is approved.', detected_at: now, status: 'open', data_hash: dataHash });

const hasCriticalSchemaError = schemaIssues.some(issue => issue.severity === 'error');
const dataIndexRows = [
  { index_id: 'IDX-' + gameCode + '-' + month + '-UserCohort', game_code: gameCode, period_key: month, month, week_start_date: '', week_end_date: '', channel: 'ALL', master_file_id: masterFileId, target_sheet: 'UserCohort', range_ref: '', data_hash: dataHash, record_count: userCohortRows.length, last_updated_at: now },
  { index_id: 'IDX-' + gameCode + '-' + month + '-DAUDaily', game_code: gameCode, period_key: month, month, week_start_date: '', week_end_date: '', channel: 'ALL', master_file_id: masterFileId, target_sheet: 'DAUDaily', range_ref: '', data_hash: dataHash, record_count: dauDailyRows.length, last_updated_at: now },
  { index_id: 'IDX-' + gameCode + '-' + month + '-ChannelMonthly', game_code: gameCode, period_key: month, month, week_start_date: '', week_end_date: '', channel: 'ALL', master_file_id: masterFileId, target_sheet: 'ChannelMonthly', range_ref: '', data_hash: dataHash, record_count: channelMonthlyRows.length, last_updated_at: now }
];

const processedRows = Object.values(tabs).reduce((sum, tab) => sum + tab.rows.length, 0);
const baseFlowStatus = hasCriticalSchemaError ? 'failed' : (Object.values(tabs).some(tab => tab.status === 'partial') ? 'partial' : 'ready');
const flowStatus = rawCheckBlocked ? 'raw_not_ready' : (needsReview ? 'needs_review' : baseFlowStatus);
const shouldBlockWrite = shouldSkipWrite || needsReview || hasCriticalSchemaError;
const preparedRowCounts = {
  RawImports: rawImportRows.length,
  UserCohort: userCohortRows.length,
  ChannelDaily: channelDailyRows.length,
  ChannelWeekly: channelWeeklyRows.length,
  ChannelMonthly: channelMonthlyRows.length,
  DAUDaily: dauDailyRows.length,
  Returners: returnerRows.length,
  LateFirstLogin: lateFirstLoginRows.length,
  QualitySignals: qualitySignalRows.length,
  TransformLog: 1,
  DataIndex: dataIndexRows.length,
  PipelineLogs: 1
};
const rowsWritten = shouldBlockWrite ? 0 : Object.entries(preparedRowCounts)
  .filter(([key]) => !['QualitySignals', 'PipelineLogs'].includes(key))
  .reduce((sum, [, count]) => sum + count, 0);
const runStartedAt = runId.replace('RUN-', '');
const statusMessage = rawCheckBlocked
  ? 'Raw check is not ready: ' + (unit.raw_check_message || rawCheckStatus)
  : shouldSkipWrite
  ? 'Skipped write: same data_hash already processed for ' + gameCode + ' ' + month + '.'
  : needsReview
    ? 'Needs review: same game/month has different data_hash. previous=' + previousDataHash + ', current=' + dataHash + '. No write executed.'
    : hasCriticalSchemaError
      ? 'Failed schema validation: ' + schemaIssues.filter(issue => issue.severity === 'error').map(issue => issue.message).join(' | ')
      : 'Prepared Master payload with production schema join: registered=' + userCohortRows.length + ', dau=' + dauDailyRows.length + ', returners=' + returnerRows.length + ', late=' + lateFirstLoginRows.length + ', login_raw=' + tabs.login.rows.length;
const transformLogRows = [{
  run_id: runId,
  batch_id: batchId,
  run_started_at: runStartedAt,
  run_finished_at: now,
  workflow_name: 'CQR_N8N_Master_Data_Update',
  game_code: gameCode,
  period_key: month,
  source_file_id: unit.source_file_id,
  source_tab_name: 'ALL',
  target_sheet: 'ALL',
  rows_read: processedRows,
  rows_written: rowsWritten,
  processed_rows: processedRows,
  status: shouldSkipWrite ? 'skipped' : flowStatus,
  message: statusMessage,
  data_hash: dataHash,
  data_hash_before: previousDataHash,
  raw_check_id: rawCheckId,
  raw_check_status: rawCheckStatus,
  master_file_id: masterFileId
}];
const pipelineLogRows = [{
  run_id: runId,
  batch_id: batchId,
  workflow_name: 'CQR_N8N_Master_Data_Update',
  run_started_at: runStartedAt,
  run_finished_at: now,
  game_code: gameCode,
  period_key: month,
  source_file_id: unit.source_file_id,
  master_file_id: masterFileId,
  status: shouldSkipWrite ? 'skipped' : flowStatus,
  rows_read: processedRows,
  rows_written: rowsWritten,
  data_hash_before: previousDataHash,
  data_hash_after: dataHash,
  message: statusMessage,
  raw_check_id: rawCheckId,
  raw_check_status: rawCheckStatus
}];
const fullPayloads = {
  RawImports: rawImportRows,
  UserCohort: userCohortRows,
  ChannelDaily: channelDailyRows,
  ChannelWeekly: channelWeeklyRows,
  ChannelMonthly: channelMonthlyRows,
  DAUDaily: dauDailyRows,
  Returners: returnerRows,
  LateFirstLogin: lateFirstLoginRows,
  QualitySignals: qualitySignalRows,
  TransformLog: transformLogRows,
  DataIndex: dataIndexRows,
  PipelineLogs: pipelineLogRows
};
const emptyPayloads = Object.fromEntries(Object.keys(fullPayloads).map(key => [key, []]));
const writePayloads = shouldBlockWrite ? { ...emptyPayloads, QualitySignals: qualitySignalRows, TransformLog: transformLogRows, PipelineLogs: pipelineLogRows } : fullPayloads;

return [{ json: {
  ...unit,
  central_db_id: centralDbId,
  batch_id: batchId,
  raw_check_id: rawCheckId,
  raw_check_status: rawCheckStatus,
  master_file_id: masterFileId,
  master_data_hash: dataHash,
  previous_data_hash: previousDataHash,
  dedupe_key: dedupeKey,
  skipped_duplicate_hash: shouldSkipWrite,
  needs_review: needsReview,
  schema_issues: schemaIssues,
  raw_counts: Object.fromEntries(Object.entries(tabs).map(([k, v]) => [k, v.rows.length])),
  prepared_row_counts: preparedRowCounts,
  write_payloads: writePayloads,
  pipeline_status: shouldSkipWrite ? 'skipped' : flowStatus,
  next_step: shouldSkipWrite
    ? 'No write needed; source data hash is unchanged.'
    : needsReview
      ? 'Review same-period hash change. Run cleanup/replace policy before force run.'
      : hasCriticalSchemaError
        ? 'Fix raw schema or mapping before write.'
        : 'Write nodes completed with production schema join and dedupe hash tracking.'
}}];

const p = $json.write_payloads || {};
const writeCounts = Object.fromEntries(Object.entries(p).map(([key, rows]) => [key, Array.isArray(rows) ? rows.length : 0]));
return [{ json: {
  status: $json.pipeline_status,
  message: $json.skipped_duplicate_hash
    ? 'Skipped: data_hash is unchanged, so no rows were written.'
    : 'CQR Master payload written to Master File and Central DB.',
  game_code: $json.game_code,
  target_month: $json.target_month,
  master_file_id: $json.master_file_id,
  data_hash: $json.master_data_hash,
  previous_data_hash: $json.previous_data_hash,
  skipped_duplicate_hash: $json.skipped_duplicate_hash,
  prepared_row_counts: $json.prepared_row_counts || {},
  row_counts: writeCounts
}}];
